const tabId = 343605502;
const allBatchesFrance = await browserjs(tabId, async () => {
  const appId = window.AlgoliaOpts.app;
  const apiKey = window.AlgoliaOpts.key;
  const url = `https://${appId}-dsn.algolia.net/1/indexes/*/queries`;

  // We want to fetch all hits for 2022 and 2023 batches.
  // There are 1125 hits. We can fetch in pages of 1000 or query specifically.
  // Algolia allows hitsPerPage up to 1000.
  const fetchPage = async (page) => {
    const body = {
      requests: [
        {
          indexName: "YCCompany_production",
          params: new URLSearchParams({
            hitsPerPage: "1000",
            page: String(page),
            attributesToRetrieve: "name,slug,batch,all_locations,regions,isHiring,status,website",
            facetFilters: JSON.stringify([
              ["batch:Winter 2022", "batch:Summer 2022", "batch:Winter 2023", "batch:Summer 2023"]
            ])
          }).toString()
        }
      ]
    };
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "x-algolia-api-key": apiKey,
        "x-algolia-application-id": appId,
        "content-type": "application/json"
      },
      body: JSON.stringify(body)
    });
    return await res.json();
  };

  const page0 = await fetchPage(0);
  const page1 = await fetchPage(1);
  const allHits = [...(page0.results[0].hits || []), ...(page1.results[0].hits || [])];

  const franceCompanies = allHits.filter(h => {
    const loc = (h.all_locations || '').toLowerCase();
    const regs = (h.regions || []).map(r => r.toLowerCase());
    return loc.includes('france') || regs.includes('france');
  });

  return {
    totalHits: allHits.length,
    franceCount: franceCompanies.length,
    franceCompanies: franceCompanies.map(h => ({
      name: h.name,
      slug: h.slug,
      batch: h.batch,
      all_locations: h.all_locations,
      regions: h.regions,
      isHiring: h.isHiring,
      status: h.status
    }))
  };
});

console.log("Total hits checked:", allBatchesFrance.totalHits);
