      // In YC company pages, there's often a tab "Jobs <count>" or links under /jobs/
      const jobLinks = Array.from(doc.querySelectorAll(`a[href*="/companies/${slug}/jobs/"]`)).map(a => a.textContent.trim());

      // Also look for any link or text saying "Jobs"
      const allText = doc.body.innerText;
      const jobsTabMatch = allText.match(/Jobs\s*(\d+)/i);
      const jobsCount = jobsTabMatch ? parseInt(jobsTabMatch[1], 10) : 0;

      // Extract batch, location, status
      results.push({
        slug,
        jobsCount,
        jobListingsCount: jobLinks.length,
        jobTitles: jobLinks.slice(0, 5),
        hasJobLinks: jobLinks.length > 0
      });
    } catch (e) {
      results.push({ slug, error: e.message });
    }
  }
  return results;
}, allFranceCompanies);

