const tabId = 343605502;
const allFranceCompanies = [
  "osium-ai", "rimward", "upstream", "twenty", "hylight", 
  "escape", "bujeti", "bitstack", "windmill", "moneco", 
  "whitelab-genomics", "beyond-aero", "brainboard", "joe", 
  "sarus", "defer", "gluetrail"
];

const checkAll = await browserjs(tabId, async (slugs) => {
  const results = [];
  for (const slug of slugs) {
    try {
      const resp = await fetch(`https://www.ycombinator.com/companies/${slug}`);
      const html = await resp.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(html, 'text/html');

      // Look for the "Jobs" tab or jobs count or job links
      // In YC company pages, there's often a tab "Jobs <count>" or links under /jobs/
      const jobLinks = Array.from(doc.querySelectorAll(`a[href*="/companies/${slug}/jobs/"]`)).map(a => a.textContent.trim());

      // Also look for any link or text saying "Jobs"
      const allText = doc.body.innerText;
      const jobsTabMatch = allText.match(/Jobs\s*(\d+)/i);
      const jobsCount = jobsTabMatch ? parseInt(jobsTabMatch[1], 10) : 0;

      // Extract batch, location, status
      results.push({
        slug,
        jobsCount,
        jobListingsCount: jobLinks.length,
        jobTitles: jobLinks.slice(0, 5),
        hasJobLinks: jobLinks.length > 0
      });
    } catch (e) {
      results.push({ slug, error: e.message });
    }
  }
  return results;
}, allFranceCompanies);

console.log(JSON.stringify(checkAll, null, 2));

