const selectOtherBatches = await browserjs(tabId, () => {
  const batches = ['Winter 2023', 'Summer 2022', 'Winter 2022'];
  const res = [];
  for (const b of batches) {
    const label = Array.from(document.querySelectorAll('label')).find(l => l.textContent?.includes(b));
    const input = label?.querySelector('input');
    if (input && !input.checked) {
      input.click();
      res.push(`clicked ${b}`);
    }
  }
  return res;
});
console.log("Selected other batches:", selectOtherBatches);
await new Promise(r => setTimeout(r, 1500));

